solution:
def can_partition(nums):
    total = sum(nums)
    if total % 2:
        return False                         # an odd total can never be split into two equal halves
    target = total // 2
    can_make = [False] * (target + 1)        # can_make[s]: some group of the numbers seen so far adds up to s
    can_make[0] = True                       # the empty group
    for number in nums:
        for s in range(target, number - 1, -1):      # downwards, so each number is used at most once
            if can_make[s - number]:
                can_make[s] = True
    return can_make[target]
